import{z as l,x as o,o as A,c as s,q as B,j as t,D as a,d as n,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"失败模式与收束","description":"","frontmatter":{"title":"失败模式与收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fml-map.md","filePath":"quant/fml-map.md","lastUpdated":1791413859000}'),C={name:"quant/fml-map.md"};function d(p,E,D,F,m,c){const e=o("Mermaid");return A(),s("div",null,[E[2]||(E[2]=B('<h1 id="失败模式与收束" tabindex="-1">失败模式与收束 <a class="header-anchor" href="#失败模式与收束" aria-label="Permalink to &quot;失败模式与收束&quot;">​</a></h1><div class="epigraph"><p>失败不是反例集，是同一台机器在不同接口上的停机照；把停机照并排挂起，机器的图纸才第一次完整。</p><footer>—— 据 López de Prado, Advances in Financial Machine Learning, 2018；Arnott, Harvey and Markowitz, Journal of Financial Data Science, 2019 的口径整理</footer></div><p><a href="/quant/fml-research-workflow">上一课</a>把十课的工程装进一条带门的流水线，本课是金融 ML 工程的收束。先倒着走一遍机器：十站各自的停机照；再给课程地图。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>失败模式按站点挂账。特征层：双跑差异发散被当噪声压掉，管道漂移吃掉 alpha 而监控一路绿灯；快照反写历史，幸存者漏进训练。标签层：障碍宽度全样本调优，模型学会的是 \\(k\\) 的选择过程；唯一性权重缺失，\\(t\\) 统计量虚高约 \\(\\sqrt{5}\\) 倍。选择层：桌下尝试不进台账，\\(N\\) 被系统性低估，极值门槛失守；判据漂移，夏普不够就换 Calmar。切分层：随机折加全样本标准化，折外分数向样本内收敛。集成层：成员同源，有效成员不到两个，方差没降而复杂度照付；stacking 的二级学习器把泄漏从后门放回。解释层：SHAP 排名当特征淘汰名单，解释误差进入选择环路；探针无基线，第一次报警耗尽信任。在线层：步长在打乱顺序上调，实盘跑的不是被验收的模型；无激励期系数沿噪声漂移无人看。漂移层：原假设写成「IC 等于回测」，报警要么天天响要么从不响；重训流程没有「不交易」输出，响应永远给出新模型。审计层：审计包后置，重建的是回忆；挑战者考核挂在被审模型上，独立是名义的。工作流层：跨区通道被汇报顶替，协议仪式化；影子盘按三个月日历转正，证伪职能落空。</p><p><span class="marginnote">停机照可以类比飞机的黑匣子报告：每起事故都不是孤立的怪事，而是同一套系统在某个接口上的失效方式。对应的修理不是换个飞行员（调参数），而是改程序与检查单（修契约）——这正是「按接口读」的含义。</span></p><p><span class="marginnote">数字实例：唯一性权重缺失时，5 日逐日重叠让 \\(t\\) 统计量虚高约 \\(\\sqrt{5}\\approx 2.2\\) 倍——真实只有 1.0 的信号会被记成 2.2，轻松越过 1.96 的显著性门槛；账面上多出来的那批「显著」策略，多半是重叠计数重复报的票。</span></p>',7)),(A(),t(i,null,{default:a(()=>[r(e,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20LR%0A%20%20F1%5B%22%E5%BF%AB%E7%85%A7%E5%8F%8D%E5%86%99%E5%8E%86%E5%8F%B2%22%5D%20--%3E%20C1%5B%22%E7%89%B9%E5%BE%81%E5%93%88%E5%B8%8C%E5%AF%B9%E8%B4%A6%22%5D%0A%20%20F2%5B%22%E9%9A%9C%E7%A2%8D%20k%20%E5%85%A8%E6%A0%B7%E6%9C%AC%E8%B0%83%E4%BC%98%22%5D%20--%3E%20C2%5B%22%E6%A0%87%E7%AD%BE%E5%9B%9B%E5%85%83%E7%BB%84%22%5D%0A%20%20F3%5B%22%E6%A1%8C%E4%B8%8B%E5%B0%9D%E8%AF%95%E4%B8%8D%E8%AE%B0%E8%B4%A6%22%5D%20--%3E%20C3%5B%22N%20%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20F4%5B%22%E9%9A%8F%E6%9C%BA%E6%8A%98%E5%8A%A0%E5%85%A8%E6%A0%B7%E6%9C%AC%E6%A0%87%E5%87%86%E5%8C%96%22%5D%20--%3E%20C4%5B%22%E5%88%87%E5%88%86%E8%B7%AF%E5%BE%84%E5%8F%82%E6%95%B0%22%5D%0A%20%20F5%5B%22%E9%87%8D%E8%AE%AD%E6%B0%B8%E8%BF%9C%E7%BB%99%E6%96%B0%E6%A8%A1%E5%9E%8B%22%5D%20--%3E%20C5%5B%22%E7%9B%91%E6%8E%A7%E7%8A%B6%E6%80%81%E6%9C%BA%22%5D%0A%20%20C1%20--%3E%20T%5B%22%E6%B3%A8%E5%85%A5%E6%B5%8B%E8%AF%95%EF%BC%9A%E6%AF%8F%E6%AC%A1%E5%8F%98%E6%9B%B4%E6%8A%BD%E4%B8%A4%E5%BC%A0%E5%81%9C%E6%9C%BA%E7%85%A7%22%5D%0A%20%20C2%20--%3E%20T%0A%20%20C3%20--%3E%20T%0A%20%20C4%20--%3E%20T%0A%20%20C5%20--%3E%20T%0A%20%20T%20--%3E%20R%5B%22%E6%8A%A5%E4%B8%8D%E5%87%BA%E8%AD%A6%E7%9A%84%E6%8E%A5%E5%8F%A3%E5%BD%93%E5%9C%BA%E4%BF%AE%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[n(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>清单的用法是应力测试，不是背诵。按接口读：每张停机照都指认一份失效的对账单——特征哈希、\\(N\\) 台账、监控状态机——修复落在契约上，而不是落在参数上。把清单挂进变更流程：数据源、基础设施或模型族的每次变更，抽两张停机照做注入测试；报不出警的接口当场修，清单随系统演化，而不是挂在 wiki 上过期。</p><p><span class="marginnote">注入测试翻译成大白话：故意往系统里放一份已知的坏东西（比如偷偷改回全样本标准化），看清单上的接口报不报警——像消防演习放烟测的是烟感器，不是消防员。报警失灵当场修，这比任何评审PPT都诚实。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>十张停机照有同一个根：每一层都有一台「局部看起来在进步」的诱惑机器——泄漏让折外分数变好，漏记让 \\(N\\) 变小，回退让可用率变好，重训让响应总有产出。单点防御都会被相邻层的激励绕开，所以地图的读法是接口：每份契约——特征哈希、标签四元组、\\(N\\) 台账、切分参数、监控状态机——都是两层之间的对账单，失败模式清单是接口的应力测试集。三句话带走这门课：训练与实盘读同一个真相；每一次选择都被计数；每一个响应都有合法出口——协议的弃权、集成的保留单成员、漂移的停机。流程的终点不是「有了模型」，而是「无论有没有模型，账都对得上」。</p>',5)),(A(),t(i,null,{default:a(()=>[r(e,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20FS%5B%22%E7%89%B9%E5%BE%81%EF%BC%9A%E5%8D%95%E5%AE%9A%E4%B9%89%E5%8F%8C%E7%89%A9%E5%8C%96%22%5D%20--%3E%20LB%5B%22%E6%A0%87%E7%AD%BE%EF%BC%9A%E5%9B%9B%E5%85%83%E7%BB%84%E5%86%BB%E7%BB%93%22%5D%0A%20%20LB%20--%3E%20SEL%5B%22%E5%8D%8F%E8%AE%AE%EF%BC%9A%E5%80%99%E9%80%89%E3%80%81%E5%88%A4%E6%8D%AE%E3%80%81N%20%E5%8F%B0%E8%B4%A6%22%5D%0A%20%20SEL%20--%3E%20CV%5B%22%E5%88%87%E5%88%86%EF%BC%9A%E5%9D%97%E3%80%81%E6%B8%85%E6%B4%97%E3%80%81%E8%B7%AF%E5%BE%84%22%5D%0A%20%20CV%20--%3E%20ENS%5B%22%E9%9B%86%E6%88%90%EF%BC%9A%E7%9B%B8%E5%85%B3%E6%80%A7%E9%A2%84%E7%AE%97%22%5D%0A%20%20ENS%20--%3E%20XAI%5B%22%E8%A7%A3%E9%87%8A%EF%BC%9A%E7%B0%87%E7%BA%A7%E5%8F%A3%E5%BE%84%E5%8A%A0%E6%B6%88%E8%9E%8D%22%5D%0A%20%20XAI%20--%3E%20OL%5B%22%E5%9C%A8%E7%BA%BF%EF%BC%9A%E6%AD%A5%E9%95%BF%E8%B4%A6%E4%B8%8E%E6%BB%A4%E6%B3%A2%E5%8F%A3%E5%BE%84%22%5D%0A%20%20OL%20--%3E%20DR%5B%22%E6%BC%82%E7%A7%BB%EF%BC%9A%E4%B8%89%E7%B1%BB%E5%88%86%E6%B5%81%22%5D%0A%20%20DR%20--%3E%20AUD%5B%22%E5%AE%A1%E8%AE%A1%EF%BC%9A%E5%8C%85%E4%B8%8E%E6%9C%89%E6%95%88%E6%8C%91%E6%88%98%22%5D%0A%20%20AUD%20--%3E%20WF%5B%22%E5%B7%A5%E4%BD%9C%E6%B5%81%EF%BC%9A%E9%97%A8%E4%B8%8E%E5%9B%9E%E6%B5%81%22%5D%0A%20%20WF%20--%3E%7C%22'%E8%A1%B0%E5%87%8F%E9%A2%84%E7%AE%97%E4%B8%8E%E7%89%B9%E5%BE%81%E6%97%8F%E5%86%99%E5%9B%9E'%22%7C%20FS%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[n(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=B('<p><span class="marginnote">最贵的停机照是「绿灯照」：所有监控正常，净值却缓慢跑输。它不触发任何一层的状态机，只有把扣费后残差与事前衰减预算逐期对账才能发现——主路径的判据必须事前写成数字，而不是事后看图，理由在此。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>清单不穷尽：失败模式随市场制度与工具栈演化，台账与复盘是清单的更新机制。地图与相邻课程的接口：上游吃因子研究交付的信号清单与<a href="/quant/pf-case-map">组合构建</a>的执行假设，下游把信号与衰减预算交回组合层与执行层；深度模型在定价与信号上的延伸是深度学习与定价课程的对象，另类数据源的工程是另类数据课程的对象。收束也不给「最佳实践参数包」：窗长、\\(E\\)、影子时长、衰减预算都是组织按自身信号与成本标定出来的，本课程给的是标定与验收的方法，不是替你标定好的数。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>失败的共同根是局部在进步：每层的诱惑机器都能被相邻层的激励重新打开。</li><li>十站的契约就是十张对账单：哈希、四元组、台账、路径、状态机，失败模式清单是接口的应力测试集。</li><li>三个合法出口贯穿全程：协议弃权、保留最强单成员、漂移停机；永远产出新模型的系统最可疑。</li><li>课程地图十站：特征、标签、协议、切分、集成、解释、在线、漂移、审计、工作流；上游接因子与组合，下游接执行。</li><li>出处：López de Prado, <em>Advances in Financial Machine Learning</em>, Wiley, 2018；Arnott, Harvey and Markowitz, <em>Journal of Financial Data Science</em>, 2019；Harvey, Liu and Zhu, <em>RFS</em>, 2016。</li></ul>',5))])}const u=l(C,[["render",d]]);export{h as __pageData,u as default};
